cd /home/salboaie/work/sopworlds/soplang-nlu/eval-results/2026-11-28-vibe-pilot/deepseek-v4-1-flash-1017 && node -e '
const fs=require("fs");
const packet=new Map(fs.readFileSync("packet-1.jsonl","utf8").split("\n").filter(l=>l.trim()).map(l=>{const o=JSON.parse(l);return [o.n,o.text]}));
const vs=fs.readFileSync("verdicts-1.jsonl","utf8").split("\n").filter(l=>l.trim()).map(l=>JSON.parse(l));
const plain=t=>t.toLowerCase().replace(/\s+/g," ").trim();
let bad=[];
for(const v of vs){ if(v.grade==="L8") continue; const text=plain(packet.get(v.n)); const quotes=[...v.note.matchAll(/\x27([^\x27]*)\x27/g)].map(m=>plain(m[1])); const ok=quotes.filter(q=>text.includes(q)); if(!quotes.length||ok.length!==quotes.length) bad.push(v.n+" quotes="+JSON.stringify(quotes)+" found="+JSON.stringify(ok)); }
console.log(bad.length?bad.join("\n"):"all quoted spans appear in their message");'

